function bindCarpathia(){
const chapters=[...document.querySelectorAll(".carpathia-chapter")],details=[...document.querySelectorAll(".cp-detail")];
chapters.forEach((btn,i)=>btn.addEventListener("click",()=>{
 chapters.forEach((b,j)=>{b.classList.toggle("is-active",j===i);b.setAttribute("aria-expanded",String(j===i))});
 details.forEach((d,j)=>d.classList.toggle("is-open",j===i));
 details[i]?.scrollIntoView({behavior:"smooth",block:"nearest"});
}));
const seasons=[...document.querySelectorAll(".cp-season")],panels=[...document.querySelectorAll(".cp-season-panel")];
const seasonImages=seasons.map(btn=>btn.querySelector(".cp-season-image"));
const seasonSlots=seasons.map(btn=>btn.querySelector(".cp-season-media"));
const seasonPanelSlots=panels.map(panel=>panel.querySelector(".cp-season-panel-media"));
let activeSeason=-1;
seasons.forEach((btn,i)=>btn.addEventListener("click",()=>{
 if(activeSeason===i)return;
 if(activeSeason>=0){
  seasonSlots[activeSeason]?.appendChild(seasonImages[activeSeason]);
  seasons[activeSeason].classList.remove("is-active");
  seasons[activeSeason].setAttribute("aria-expanded","false");
  panels[activeSeason].classList.remove("is-active");
  panels[activeSeason].setAttribute("aria-hidden","true");
 }
 seasonPanelSlots[i]?.appendChild(seasonImages[i]);
 btn.classList.add("is-active");
 btn.setAttribute("aria-expanded","true");
 panels[i].classList.add("is-active");
 panels[i].setAttribute("aria-hidden","false");
 activeSeason=i;
}));
const inputs=[...document.querySelectorAll("[data-cp-key]")],results=document.querySelector("[data-cp-results]");
const render=()=>{
 const complete=inputs.every(x=>x.value.trim()!=="");
 inputs.forEach(x=>x.setAttribute("aria-invalid",String(x.value.trim()==="")));
 if(!complete){results.innerHTML='<div class="cp-result-empty"><span>СЦЕНАРНАЯ МОДЕЛЬ</span><b>Введите 7 параметров</b><p>Результат появится только после полного заполнения. Никаких значений по умолчанию.</p></div>';return}
 const v=Object.fromEntries(inputs.map(x=>[x.dataset.cpKey,Number(x.value)]));
 if(Object.values(v).some(x=>!Number.isFinite(x)||x<0)||v.occupancy>100){results.innerHTML='<div class="cp-result-error"><b>Проверьте данные</b><p>Числа должны быть неотрицательными, а загрузка — от 0 до 100%.</p></div>';return}
 const rooms=v.rooms,roomRevenue=rooms*v.occupancy/100*v.adr*v.days,gross=roomRevenue+v.extra,op=gross-v.opex,roi=v.capex?op/v.capex*100:0,payback=op>0&&v.capex&&v.days?v.capex/op*v.days/365:0;
 const rows=[["Размещение",roomRevenue,"₴"],["Общая выручка",gross,"₴"],["Операционный результат",op,"₴"],["Доходность за период",roi,"%"],["Срок возврата вложений",payback,"лет"]];
 results.innerHTML='<div class="cp-result-live"><span>РАСЧЁТ ПО ВВЕДЁННЫМ ДАННЫМ</span><h3>Результат сценария</h3>'+rows.map((r,i)=>'<div class="cp-result-row '+(i===2?'is-main':'')+'"><span>'+r[0]+'</span><b>'+formatValue(r[1],r[2]==="%"?"percent":"")+(r[2]==="₴"?" ₴":"")+(r[2]==="%"?"":"")+'</b></div>').join("")+'<small>Расчёт показывает взаимосвязь введённых данных и не является прогнозом или гарантией доходности.</small></div>';
};
inputs.forEach(x=>x.addEventListener("input",render));
document.querySelector("[data-cp-reset]")?.addEventListener("click",()=>{inputs.forEach(x=>x.value="");render()});
render();
}
