async function journalPage(){
nav("journal");const app=document.getElementById("app"),stored=sessionStorage.getItem("mmw_company_order_access");
if(!stored){app.innerHTML='<section class="page-intro"><span class="eyebrow">MMW-COMPANY · ЖУРНАЛ</span><h1>Доступ к заявке</h1><p class="lead">Введите номер телефона, указанный в заявке, и пятизначный код доступа.</p><div class="journal-access"><input id="access-phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="+380 67 123 45 67"><input id="access-code" inputmode="numeric" maxlength="5" autocomplete="one-time-code" placeholder="5 цифр"><button class="button" id="open-code">Открыть заявку</button></div><div id="journal-result"></div></section>';document.getElementById("open-code").onclick=async()=>{const phone=document.getElementById("access-phone").value.trim(),code=document.getElementById("access-code").value.trim(),btn=document.getElementById("open-code");btn.disabled=true;try{const r=await fetch("/api/order-access",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone,code})}),j=await r.json();if(!r.ok)throw new Error(j.error||"Ошибка доступа");sessionStorage.setItem("mmw_company_order_access",JSON.stringify({phone,code}));await journalPage();}catch(e){document.getElementById("journal-result").innerHTML='<div class="form-error">'+esc(e.message)+"</div>"}finally{btn.disabled=false}};return}
try{const a=JSON.parse(stored),r=await fetch("/api/order-access",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)}),j=await r.json();if(!r.ok)throw new Error(j.error||"Доступ к заявке недействителен");app.innerHTML='<section class="page-intro"><span class="eyebrow">MMW-COMPANY · ЖУРНАЛ</span><h1>Заявка '+esc(j.order.id)+'</h1><p class="lead">Статус, состав заявки и PDF-документ.</p><div class="journal-list">'+orderCard(j.order)+'</div><button class="button button-secondary" id="close-order">Закрыть заявку</button></section>';document.getElementById("close-order").onclick=()=>{sessionStorage.removeItem("mmw_company_order_access");window.location.hash="#/journal"}}catch(e){sessionStorage.removeItem("mmw_company_order_access");app.innerHTML='<section class="page-intro"><h1>Доступ закрыт</h1><p>'+esc(e.message)+'</p><button class="button" onclick="location.hash=\'#/journal\'">Ввести данные заново</button></section>'}
}
function orderCard(o){return '<article class="order-card"><div><span class="eyebrow">'+esc(o.status)+'</span><h3>'+esc(o.id)+'</h3><p>'+new Date(o.createdAt).toLocaleString("ru-RU")+' · '+money2(o.total)+'</p><div>'+o.items.map(x=>'<span class="order-item">'+esc(x.name)+' × '+x.qty+'</span>').join("")+'</div></div><a class="button button-small" target="_blank" href="/api/orders/'+encodeURIComponent(o.id)+'/pdf?code='+encodeURIComponent(o.accessCode)+'">PDF</a></article>'}


async function adminJournalPage(){
nav("catalog");const app=document.getElementById("app"),key=sessionStorage.getItem("mmw_company_admin_key")||prompt("Ключ журнала MMW-COMPANY");
if(!key){app.innerHTML='<section class="page-intro"><h1>Журнал закрыт</h1><p>Администраторский ключ не введён.</p></section>';return}
sessionStorage.setItem("mmw_company_admin_key",key);
try{const r=await fetch("/api/admin/orders",{headers:{"x-admin-key":key}});const j=await r.json();if(!r.ok)throw new Error(j.error||"Доступ запрещён");app.innerHTML='<section class="page-intro"><span class="eyebrow">MMW-COMPANY · ЖУРНАЛ ЗАЯВОК</span><h1>Журнал заявок</h1><p class="lead">Обработка коммерческих обращений.</p><div class="journal-list">'+(j.orders||[]).map(o=>'<article class="order-card"><div><span class="eyebrow">'+esc(o.status)+'</span><h3>'+esc(o.id)+'</h3><p>'+new Date(o.createdAt).toLocaleString("ru-RU")+' · '+money2(o.total)+' · '+esc(o.customerName)+' · '+esc(o.phone)+'</p><div>'+o.items.map(x=>'<span class="order-item">'+esc(x.name)+' × '+x.qty+'</span>').join("")+'</div></div><div class="journal-actions"><a class="button button-small" target="_blank" href="/api/orders/'+encodeURIComponent(o.id)+'/pdf?code='+encodeURIComponent(o.accessCode)+'">PDF</a><select data-status="'+esc(o.id)+'"><option>Новая</option><option>В работе</option><option>Ожидает уточнения</option><option>Выполнена</option><option>Отменена</option></select></div></article>').join("")+'</div></section>';document.querySelectorAll("[data-status]").forEach(x=>{const o=(j.orders||[]).find(a=>a.id===x.dataset.status);if(o)x.value=o.status;x.onchange=async()=>{await fetch("/api/admin/orders/"+encodeURIComponent(x.dataset.status)+"/status",{method:"PATCH",headers:{"Content-Type":"application/json","x-admin-key":key},body:JSON.stringify({status:x.value})})}})}catch(e){sessionStorage.removeItem("mmw_company_admin_key");app.innerHTML='<section class="page-intro"><h1>Доступ закрыт</h1><p>'+esc(e.message)+'</p></section>'}
}
function route(){
const raw=location.hash.replace(/^#\/?/,""),parts=raw.split("/").filter(Boolean);
if(!(parts[0]==="project"&&parts[1]))document.body.removeAttribute("data-project");
if(parts[0]==="project"&&parts[1])project(parts[1],parts[2]);
else if(parts[0]==="projects")projects();
else if(parts[0]==="catalog")catalogPage(parts[1]);
else if(parts[0]==="cart")catalogPage();
else if(parts[0]==="contact")contactPage();
else if(parts[0]==="journal")journalPage();
else if(parts[0]==="admin-journal")adminJournalPage();
else home();
const menu=document.getElementById("menu"),navEl=document.getElementById("nav");if(menu&&!menu.dataset.bound){menu.dataset.bound="1";menu.onclick=()=>{const open=navEl.classList.toggle("open");menu.setAttribute("aria-expanded",String(open));};}
}
addEventListener("hashchange",route);
route();